//go:build ignore

// Command generate produces internal/ingestion/fixture/testdata/dev_dataset.json,
// the checked-in dev/test dataset fixture.Provider replays for
// cmd/argus-worker's dev-fixture-ingest mode (see that package's own
// docs for the ADR-007 boundary this exists inside of).
//
// The price series is synthetic and fully owned: a small, deterministic
// random walk with an engineered skeleton spliced into its start --
// cold-start swing establishment, a liquidity sweep that sets a
// protected low, a sweep-validated break of structure (BOS), and an
// order block -- verified, while this generator was being built, by
// actually ingesting its output through the real ingestion.Service and
// analysis.Engine against a scratch Postgres instance and confirming
// setups.Reconcile walks a setup from Detected through Actionable. The
// remainder is unscripted random walk, included for volume and to let
// further organic structure emerge on its own, not because every
// candle in it was individually designed.
//
// No network calls, no external data, no licensing question: every
// value here is generated by this file. Run with:
//
//	go run internal/ingestion/fixture/testdata/generate.go
//
// from the repo root. Re-running regenerates the same file byte-for-
// byte (fixed PRNG seed), so this is provenance documentation, not a
// build step anything else depends on -- the checked-in JSON is what
// ships, this file is how it was made.
package main

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"time"
)

// These mirror internal/ingestion's ProviderInstrument/ProviderCandle
// shapes field-for-field (this file is deliberately standalone, see
// the package doc) so the JSON it writes decodes directly into those
// types via internal/ingestion/fixture.LoadDataFile.
type providerInstrument struct {
	Symbol             string   `json:"Symbol"`
	AssetClass         string   `json:"AssetClass"`
	BaseAsset          string   `json:"BaseAsset"`
	QuoteAsset         string   `json:"QuoteAsset"`
	ContractType       string   `json:"ContractType"`
	PriceDecimalPlaces int32    `json:"PriceDecimalPlaces"`
	QtyDecimalPlaces   int32    `json:"QtyDecimalPlaces"`
	TickSize           string   `json:"TickSize"`
	QtyStepSize        string   `json:"QtyStepSize"`
	ContractSize       string   `json:"ContractSize"`
	PipSize            string   `json:"PipSize"`
	SupportedIntervals []string `json:"SupportedIntervals"`
}

type providerCandle struct {
	Symbol   string    `json:"Symbol"`
	OpenTime time.Time `json:"OpenTime"`
	Open     string    `json:"Open"`
	High     string    `json:"High"`
	Low      string    `json:"Low"`
	Close    string    `json:"Close"`
	Volume   string    `json:"Volume"`
	IsFinal  bool      `json:"IsFinal"`
}

type dataFile struct {
	Instruments []providerInstrument        `json:"Instruments"`
	Candles     map[string][]providerCandle `json:"Candles"`
}

type bar struct {
	idx                    int
	open, high, low, close int64
}

var base = time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)

func t(idx int) time.Time { return base.Add(time.Duration(idx) * time.Minute) }

// walker builds a monotonic-leg price path, one bar per candle, with
// zero wick on every ordinary bar (so highs/lows always exactly track
// open/close, which makes every interior bar of a monotonic leg
// provably unable to form a spurious pivot -- an ascending leg's right
// neighbors always have a higher high, a descending leg's left
// neighbors always have a higher low, so the swing detector's strict
// inequalities can never both hold for a middle bar). gap is applied
// at the first bar of every leg, so a turning point's own extreme is
// never tied by the leg that leaves it.
type walker struct {
	idx   int
	price int64
	bars  []bar
}

func newWalker(startIdx int, startPrice int64) *walker {
	return &walker{idx: startIdx, price: startPrice}
}

func (w *walker) leg(toIdx int, toPrice int64, gapAway int64) {
	n := toIdx - w.idx
	if n <= 0 {
		panic(fmt.Sprintf("leg: toIdx %d must be after current idx %d", toIdx, w.idx))
	}
	start := w.price
	if toPrice > start {
		start += gapAway
	} else if toPrice < start {
		start -= gapAway
	}
	open := start
	for i := 1; i <= n; i++ {
		close := toPrice
		if i < n {
			close = start + (toPrice-start)*int64(i)/int64(n)
		}
		h := max64(open, close)
		l := min64(open, close)
		w.bars = append(w.bars, bar{idx: w.idx + i, open: open, high: h, low: l, close: close})
		open = close
	}
	w.idx = toIdx
	w.price = toPrice
}

func (w *walker) hold(n int) {
	for i := 1; i <= n; i++ {
		w.bars = append(w.bars, bar{idx: w.idx + i, open: w.price, high: w.price, low: w.price, close: w.price})
	}
	w.idx += n
}

// wickLow appends one bar that otherwise continues the current leg's
// direction (open = current price, close = toPrice) but with an
// explicit low beyond what the open/close body alone would produce --
// the one place this script needs a real wick, since a sweep is
// defined by piercing a level intra-candle and reclaiming on the same
// candle's close.
func (w *walker) wickLow(toPrice, explicitLow int64) {
	h := max64(w.price, toPrice)
	w.bars = append(w.bars, bar{idx: w.idx + 1, open: w.price, high: h, low: explicitLow, close: toPrice})
	w.idx++
	w.price = toPrice
}

func max64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}
func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

// skeleton builds the hand-engineered, organically-confirmable part of
// the series: cold-start bullish establishment, a sweep + protected low
// (which also later qualifies as structural liquidity on its own
// merits -- discount, intact, shape-passing, so a second, separate
// structural-liquidity pivot is not needed and would conflict: any
// swing sitting between the protected low and the order block's entry
// has its own intactness breached the moment price later reaches
// entry, since reaching entry means dipping below it too), a
// sweep-validated BOS, and an order block -- the organic equivalent of
// what analysis's own test fixtures short-cut via seedSwing, but
// produced from raw OHLC so the real ingestion pipeline confirms every
// pivot itself.
func skeleton(startPrice int64) []bar {
	w := newWalker(0, startPrice)
	w.hold(4) // flat open, nothing to establish yet

	// L0, H0, L1 (> L0), H1 (> H0) -> bullish established once H1
	// confirms. H1 set well above L0/L1 (not just barely above H0) so
	// the active range's equilibrium leaves real headroom for an order
	// block that must sit both above the sweep's own reclaim level and
	// still in discount. No hold() immediately follows any peak/
	// trough: a flat hold ties the peak's own high (or trough's own
	// low) exactly, which disqualifies it as a pivot. The next leg's
	// own first bar already provides the "right-side" context a pivot
	// needs, moving away from the peak immediately via its own gap.
	w.leg(6, startPrice-500, 0)
	w.leg(14, startPrice, 10)
	w.leg(18, startPrice-300, 10)
	w.leg(24, startPrice+1000, 10)

	// Sweep + protected low: dip below L1 and reclaim above it in the
	// same candle (idx28), which is also a valid pivot low against its
	// own neighbors (nothing else approaches this level again until
	// the deliberate trigger dip much later). A short retracement
	// (idx29) immediately after the reclaim is the order block: its
	// body stays above L1's level (so it does not itself trigger a
	// CHOCH), and it must sit at or below the active range's
	// equilibrium to be usable as a POI at all.
	w.leg(27, startPrice-100, 10)
	w.wickLow(startPrice-290, startPrice-1000)
	w.leg(29, startPrice-295, 0)
	w.leg(34, startPrice+1100, 10)

	// The following opposite-type (high) swing L2's own shape test
	// needs, confirmed well before the hold/trigger phases. Kept below
	// H1: a close above H1 would mint a second BOS, which would make
	// order-block resolution track that newer break instead --
	// displacing the order block above with whatever bearish candle
	// most recently preceded the new break, not guaranteed to still be
	// in discount.
	w.leg(38, startPrice+600, 10)
	w.leg(42, startPrice+900, 10)

	// Hold actionable: stay comfortably above the order block's entry,
	// below H1, and above the protected low.
	w.leg(49, startPrice+850, 10)
	w.hold(14)

	// Trigger: wick into the order block zone, close back out above
	// it, staying above the protected low so L2's own intactness
	// survives this step.
	w.wickLow(startPrice+800, startPrice-350)
	w.hold(19)

	return w.bars
}

func toProviderCandle(symbol string, b bar) providerCandle {
	return providerCandle{
		Symbol: symbol, OpenTime: t(b.idx),
		Open: fmt.Sprintf("%d.00", b.open), High: fmt.Sprintf("%d.00", b.high),
		Low: fmt.Sprintf("%d.00", b.low), Close: fmt.Sprintf("%d.00", b.close),
		Volume: "1.0", IsFinal: true,
	}
}

// series builds one symbol's full candle series: the engineered
// skeleton followed by a deterministic random walk out to totalBars,
// continuing from wherever the skeleton left price. seed is per-symbol
// so two symbols sharing this generator do not produce byte-identical
// padding.
func series(startPrice int64, totalBars int, seed int64) []bar {
	bars := skeleton(startPrice)
	rng := rand.New(rand.NewSource(seed))
	last := bars[len(bars)-1].close
	padStart := bars[len(bars)-1].idx + 1
	for i := 0; padStart+i < totalBars; i++ {
		delta := rng.Int63n(21) - 10
		o := last
		c := last + delta
		h := max64(o, c) + rng.Int63n(10)
		l := min64(o, c) - rng.Int63n(10)
		bars = append(bars, bar{idx: padStart + i, open: o, high: h, low: l, close: c})
		last = c
	}
	return bars
}

const totalBars = 1500

func main() {
	symbols := []struct {
		symbol     string
		base       string
		quote      string
		startPrice int64
		seed       int64
	}{
		{"BTC-PERP", "BTC", "USD", 67000, 1},
		{"ETH-PERP", "ETH", "USD", 67000, 2},
	}

	out := dataFile{Candles: map[string][]providerCandle{}}
	for _, s := range symbols {
		out.Instruments = append(out.Instruments, providerInstrument{
			Symbol: s.symbol, AssetClass: "crypto_perp", BaseAsset: s.base, QuoteAsset: s.quote,
			ContractType: "perpetual", PriceDecimalPlaces: 0, QtyDecimalPlaces: 0,
			TickSize: "1", QtyStepSize: "1", SupportedIntervals: []string{"1m"},
		})
		bars := series(s.startPrice, totalBars, s.seed)
		candles := make([]providerCandle, len(bars))
		for i, b := range bars {
			candles[i] = toProviderCandle(s.symbol, b)
		}
		out.Candles[s.symbol] = candles
	}

	f, err := os.Create("internal/ingestion/fixture/testdata/dev_dataset.json")
	if err != nil {
		panic(err)
	}
	defer f.Close()
	enc := json.NewEncoder(f)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		panic(err)
	}
	fmt.Println("wrote", len(symbols), "symbols,", totalBars, "bars each")
}
